async function synchronize(){
 if(syncing||cloud?.busy)return;
 if(document.querySelector('dialog[open]')||hasUnsavedForm()){syncError='Actualisation en attente : terminez ou fermez la saisie en cours.';refreshHomeStatus();return;}
 syncing=true;syncError='';refreshHomeStatus();const revision=cloud?.revision;
 try{
 if(cloud){const state=await cloud.read(false);if(!valid(state.payload))throw Error('Données reçues invalides : mise à jour bloquée.');if(cloud.busy||revision!==cloud.revision||document.querySelector('dialog[open]')||hasUnsavedForm())return;if(state.revision!==revision){data=upgrade(state.payload);cloud.revision=state.revision;pendingMigration=state.migration&&!state.migration.validated_at?{receipt:state.migration.id,document:state.payload}:null;render();}}
 else if(!memoryOnly&&!storageNeedsRecovery){const raw=localStorage.getItem(KEY);if(raw){const next=JSON.parse(raw);if(!valid(next))throw Error('Sauvegarde locale invalide : les données affichées sont conservées.');if(canonical(upgrade(next))!==canonical(data)){data=next;render();}}}
 lastUpdated=new Date();
 }catch(error){syncError=`Actualisation interrompue : ${error.message} Dernière réception à ${lastUpdated.toLocaleTimeString('fr-FR',{timeZone:'Europe/Paris'})}.`;}
 finally{syncing=false;refreshHomeStatus();}
}
for(const id of ['homePrioritySector','homePriorityTeam','homePriorityStatus','homePrioritySort'])$('#'+id).onchange=renderHome;
$('#homePriorityReset').onclick=()=>{for(const id of ['homePrioritySector','homePriorityTeam','homePriorityStatus'])$('#'+id).value='';$('#homePrioritySort').value='date';renderHome();};
$('#homeSync').onclick=synchronize;$('#homeLogo').onclick=event=>{event.preventDefault();displayedWeekOffset=0;setView('home');};$('#homeMaterial').onclick=()=>setView('material');$('#homeKpi').onclick=()=>setView('kpi');$('#homeAdd').onclick=()=>edit();
$('#homePreviousWeek').onclick=()=>{displayedWeekOffset--;renderWeeklyCalendar()};$('#homeNextWeek').onclick=()=>{displayedWeekOffset++;renderWeeklyCalendar()};$('#homeCurrentWeek').onclick=()=>{displayedWeekOffset=0;renderWeeklyCalendar()};
setInterval(synchronize,20000);window.addEventListener('storage',event=>{if(!cloud&&event.key===KEY)synchronize()});document.addEventListener('visibilitychange',()=>{if(!document.hidden)synchronize()});

function updateLossFields(){const lost=$('#controlForm').elements.result.value==='Introuvable';$('#lossHelp').hidden=!lost;$('#controlForm').elements.observations.required=lost;}

function accountName(){return cloud?.session?.user?.email||'Prototype local — compte non authentifié'}
function checkDuplicates(){let ok=true;for(const field of ['identifier','serialNumber']){const input=$('#equipmentForm').elements[field];const value=normalize(input.value);const duplicate=value&&data.equipment.some(e=>e.id!==editing&&normalize(e[field])===value);const message=duplicate?(field==='identifier'?'Équipement déjà existant':'Numéro de série déjà existant'):'';input.setCustomValidity(message);input.setAttribute('aria-invalid',String(!!duplicate));$('#'+field+'Error').textContent=message;if(duplicate)ok=false}return ok}
for(const field of ['identifier','serialNumber'])$('#equipmentForm').elements[field].addEventListener('input',checkDuplicates);
function ownerOptions(current=''){const select=$('#equipmentForm').elements.owner;select.innerHTML='<option value="">Non renseigné</option>'+data.owners.map(o=>`<option value="${esc(o)}">${esc(o)}</option>`).join('');select.value=current}
$('#addOwner').onclick=async()=>{const name=prompt('Nom du propriétaire à ajouter à la liste :');if(!name?.trim())return;const owner=name.trim();if(owner.length>160){$('#equipmentError').textContent='Le nom du propriétaire est limité à 160 caractères.';return}const existing=data.owners.find(o=>normalize(o)===normalize(owner));if(existing){ownerOptions(existing);return}if(await save({...data,owners:[...data.owners,owner]}))ownerOptions(owner)};
async function save(next,replace=false){next=freezeTracking(upgrade(next),data,today(),accountName());if(storageNeedsRecovery&&!replace){$('#message').textContent='Enregistrement bloqué pour préserver les données existantes. Importez une sauvegarde valide.';return false}try{if(cloud){if(replace)throw Error('Le remplacement global est interdit en mode cloud. Utilisez la migration initiale dans Paramètres > Données.');await cloud.write(next);}else if(!memoryOnly){try{localStorage.setItem(KEY,JSON.stringify(next))}catch(error){if(error.name!=='SecurityError')throw error;memoryOnly=true;$('#storageNotice').hidden=false}}data=next;lastUpdated=new Date();syncError='';dirtyForms.delete(document.activeElement?.closest('form'));storageNeedsRecovery=false;$('#export').disabled=false;render();return true}catch(error){$('#message').textContent=cloud?error.message:'Enregistrement impossible : stockage plein ou indisponible. Les nouvelles données ne sont pas sauvegardées. Exportez une sauvegarde.';return false}}
let controlContext='normal';
function lastArchive(e){return [...(e.archiveHistory??[])].reverse().find(a=>a.type==='archive')}
function needsScrapControl(e){return e.archived&&archiveReason(e)==='Mis au rebut'&&lastArchive(e)?.workflow!=='memoryflow-archive'&&!lastArchive(e)?.controlId}
function equipmentLabel(e){return `<b class="equipment-name">${esc(equipmentName(e))}</b><small>Numéro interne : ${esc(e.identifier)}</small><small>N° série : ${esc(e.serialNumber)||'Non renseigné'}</small><small>ID : ${e.siteId}</small>`}
function lastResult(e){if(materialArchived(e)&&lastArchive(e)?.workflow==='memoryflow-archive')return 'Mis au rebut — déclaration MemoryFlow';if(needsScrapControl(e))return 'Mis au rebut — contrôle à compléter';if(e.archived&&archiveReason(e)==='Mis au rebut'){const control=e.controls.find(c=>c.id===lastArchive(e)?.controlId);if(control)return control.result}const last=latest(e);if(e.memoryFlowTracking&&(!last||e.memoryFlowTracking.lastDate>last.date))return 'Date déclarée : '+fmt(e.memoryFlowTracking.lastDate)+' · résultat non renseigné';return last?.result||'Aucun contrôle'}
function archiveReason(e){return e.archived?[...(e.archiveHistory??[])].reverse().find(a=>a.type==='archive')?.reason||'':''}
function materialArchived(e){return !!e.archived&&!lossArchived(e);}
function archiveRowClass(e){if(e.archived)return `archived-row ${archiveReason(e)==='Mis au rebut'?'scrapped-row':archiveReason(e)==='Équipement perdu'?'lost-row':''}`;return {'En retard':'deadline-late-row','À faire':'deadline-soon-row','Échéance à plus d’un mois':'deadline-current-row','Situation à vérifier':'deadline-unknown-row'}[status(e,today())]||'deadline-unknown-row'}
function deadlineLabel(value){return ({'À faire':'À contrôler bientôt','Échéance à plus d’un mois':'À jour','Situation à vérifier':'Échéance à définir'})[value]||value;}
function badge(e){if(lossArchived(e))return '<span class="badge lost-badge">Introuvable</span>';let s=status(e,today(),data.anticipation);if(s==='Archivé'){const reason=archiveReason(e);return `<span class="badge archive-badge ${reason==='Mis au rebut'?'scrapped-badge':reason==='Équipement perdu'?'lost-badge':''}">${esc(reason)||'Archivé'}</span>`}if(s==='Situation à vérifier')return `<button class="badge unknown date-link" data-deadline="${e.id}" aria-label="Définir la date du prochain contrôle de ${esc(e.identifier)}">Échéance à définir</button>`;return `<span class="badge ${s==='En retard'?'late':(s==='À venir'||s==='À faire')?'soon':s==='Situation à vérifier'?'unknown':''}">${deadlineLabel(s)}</span>`}
let displayedWeekOffset=0;
function renderWeeklyCalendar(){const start=shiftDate(weekStart(today()),displayedWeekOffset*7),days=weeklySchedule(data.equipment,start),equipmentById=new Map(data.equipment.map(e=>[e.id,e]));$('#weekRange').textContent=$('#homeWeekRange').textContent=`Semaine du ${fmt(start)} au ${fmt(days[6].date)}`;$('#homeWeeklyCalendar').innerHTML=$('#weeklyCalendar').innerHTML=days.map(day=>`<section class="calendar-day ${day.date===today()?'calendar-today':''}"><h3>${new Date(day.date+'T00:00:00Z').toLocaleDateString('fr-FR',{weekday:'short',timeZone:'UTC'})}<span>${fmt(day.date).slice(0,5)}</span></h3>${day.entries.length?day.entries.map(e=>`<button class="calendar-task ${e.done?(e.late?'calendar-late':'calendar-done'):day.date<today()?'calendar-late':''}" data-calendar-equipment="${e.equipmentId}"><b>${esc(e.name)}</b><small>${esc(e.identifier)}</small><small class="calendar-assignment">Équipe : ${esc(equipmentById.get(e.equipmentId)?.team)||'—'}<br>Secteur : ${esc(equipmentById.get(e.equipmentId)?.sector)||'—'}</small><span>${e.done?(e.late?'Réalisé en retard':'✓ Réalisé'):day.date<today()?'En retard':'Date limite'}</span></button>`).join(''):'<p class="calendar-empty">Aucune VGP prévue</p>'}</section>`).join('');document.querySelectorAll('[data-calendar-equipment]').forEach(button=>button.onclick=()=>showDetail(button.dataset.calendarEquipment))}
function renderNotifications(){const alerts=equipmentAlerts(data.equipment,today());$('#notificationCount').textContent=alerts.length;$('#notificationCount').hidden=alerts.length===0;$('#notificationToggle').setAttribute('aria-label',`Notifications : ${alerts.length} équipement(s) à contrôler`);$('#notificationList').innerHTML=alerts.length?alerts.map(a=>`<button class="notification-item" data-notification-equipment="${a.equipmentId}"><b>${esc(a.name)}</b><small>${esc(a.identifier)} · Échéance ${fmt(a.date)}</small><span class="badge ${a.state==='En retard'?'late':'soon'}">${deadlineLabel(a.state)}</span></button>`).join(''):'<p class="empty">Aucun équipement à contrôler dans le mois, ni en retard.</p>';$('#notificationList').querySelectorAll('[data-notification-equipment]').forEach(button=>button.onclick=()=>{$('#notificationMenu').close();showDetail(button.dataset.notificationEquipment)})}
$('#previousWeek').onclick=()=>{displayedWeekOffset--;renderWeeklyCalendar()};$('#nextWeek').onclick=()=>{displayedWeekOffset++;renderWeeklyCalendar()};$('#currentWeek').onclick=()=>{displayedWeekOffset=0;renderWeeklyCalendar()};
