function setView(view,owner=null){currentView=view;try{history.replaceState(null,'',location.pathname+location.search+'#'+view)}catch{};$('#homeView').hidden=view!=='home';ownerFilter=owner;$('#materialView').hidden=view!=='material';$('#ownersView').hidden=view!=='owners';$('#controllersView').hidden=view!=='controllers';if(view==='controllers'){$('#controllerProfile').hidden=true;$('#controllersList').hidden=false;selectedController=null;}$('#kpiView').hidden=view!=='kpi';$('#mailSettingsView').hidden=view!=='mailSettings';$('#reportSettingsView').hidden=view!=='reportSettings';document.querySelectorAll('[data-view]').forEach(button=>{if(button.dataset.view===view)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current')});selectedOwner=null;if(view==='material'){materialScope='all';resetListFilters();ownerFilter=owner}render();if($('#navigation').open)$('#navigation').close();if($('#settingsMenu').open)$('#settingsMenu').close();if(view==='mailSettings')renderMailSettings();if(view==='reportSettings')renderReportSettings();$('#'+({home:'homeTitle',controllers:'controllersTitle',owners:'ownersTitle',material:'materialTitle',kpi:'kpiTitle',mailSettings:'mailSettingsTitle',reportSettings:'reportSettingsTitle'}[view])).focus()}
function renderKpi(){
 renderMonthlyKpi();const k=dashboard(data.equipment,today()),percent=k.percent===null?'Non applicable':`${k.percent} %`;
 $('#kpiVisual').innerHTML=`<section class="panel coverage-panel"><div><p class="eyebrow">PARC ACTIF · ÉCHÉANCES VALIDÉES</p><h2>VGP à jour</h2><p>${k.upToDate} équipement(s) avec une échéance validée non dépassée sur ${k.total} équipements actifs soumis au suivi. Les situations inconnues restent dans le dénominateur.</p><button class="legend-link" data-kpi-list="controlled">Voir les équipements à jour</button> · <button class="legend-link" data-kpi-list="active">Parc actif</button> · <button class="legend-link" data-kpi-list="missing">Sans contrôle exploitable</button> · <button class="legend-link" data-kpi-list="todo">Actions à réaliser</button><p class="foot">${k.archived-k.lostArchived} mis au rebut exclu(s) du suivi · <button class="legend-link" data-kpi-list="lostArchived">${k.lostArchived} introuvable(s) avec suivi suspendu</button>. Une échéance à jour ne certifie pas l’état de l’équipement.</p></div><button class="donut" data-kpi-list="controlled" style="--percentage:${k.percent??0}%"><div><strong id="kpi-percent" style="font-size:${k.percent===null?'18':'40'}px">${percent}</strong><span>VGP à jour</span></div></button></section><section class="stats kpi-cards"><button class="stat kpi-clickable" data-kpi-list="overdue"><small>Échus non réalisés</small><strong id="kpi-todo">${k.overdue}</strong><p class="foot">Parc actif uniquement</p></button><button class="stat kpi-clickable" data-kpi-list="undefined"><small>Situation inconnue / à valider</small><strong>${k.undefinedCount}</strong><p class="foot">Aucune échéance exploitable validée</p></button><button class="stat kpi-clickable" data-kpi-list="history"><small>Vérifications effectuées</small><strong id="kpi-performed">${k.performed}</strong><p class="foot">Introuvable exclu · historique conservé</p></button><button class="stat kpi-clickable" data-kpi-list="lostArchived"><small>Introuvables</small><strong>${k.lostArchived}</strong><p class="foot">À rechercher · suivi suspendu</p></button></section><div class="kpi-grid"><section class="panel"><h2>Résultats restant à traiter</h2><p class="foot">Dernier contrôle exploitable sur le parc actif. Aucun avis de conformité automatique.</p>${k.results.map(r=>`<button class="home-watch" data-kpi-list="result:${esc(r.label)}"><span>${esc(r.label)}</span><b>${r.count}</b></button>`).join('')}<p>${k.anomalies} anomalie(s) : résultats réparable ou à jeter.</p></section><section class="panel"><h2>VGP à jour par secteur</h2>${k.sectors.map(row=>`<button class="sector-progress" data-kpi-sector="${row.sector}"><div class="metric-label"><span>${row.sector||'Secteur non renseigné'}</span><b>${row.controlled} / ${row.total} · ${row.total?Math.round(row.controlled/row.total*100)+' %':'Non applicable'}</b></div><div class="metric-track"><span style="width:${row.total?row.controlled/row.total*100:0}%"></span></div></button>`).join('')}<button id="kpiOpenMaterial" class="secondary">Voir le matériel VGP</button></section></div>`;
 $('#sourceDatesSummary').hidden=!data.equipment.some(e=>e.memoryFlowTracking);$('#sourceDatesCount').textContent=data.equipment.filter(e=>!e.archived&&e.memoryFlowTracking).length;$('#sourceDatesList').onclick=()=>openKpiList('sourceDates');$('#kpiVisual').querySelectorAll('[data-kpi-list]').forEach(button=>button.onclick=()=>openKpiList(button.dataset.kpiList));$('#kpiOpenMaterial').onclick=()=>setView('material');$('#kpiVisual').querySelectorAll('[data-kpi-sector]').forEach(button=>button.onclick=()=>{setView('material');$('#sectorFilter').value=button.dataset.kpiSector||'unassigned';updateZoneFilter();render()});
}

function openKpiList(kind,filteredItems=null){const active=data.equipment.filter(e=>!e.archived),history=kind==='history';const statusKinds={undefined:'Situation à vérifier',overdue:'En retard',soon:'À faire',planned:'Échéance à plus d’un mois'};const titles={sourceDates:'Dates de contrôles déclarées dans MemoryFlow — résultat non renseigné',lostArchived:'Introuvables',active:'Parc actif',controlled:'VGP à jour — échéances validées non échues',missing:'Équipements jamais contrôlés',todo:'Contrôles à faire ou en retard',history:'Contrôles réalisés — historique complet',...Object.fromEntries(Object.entries(statusKinds).map(([k,v])=>[k,deadlineLabel(v)]))};const items=filteredItems?filteredItems.map(e=>({e})):kind==='lostArchived'?data.equipment.filter(lossArchived).map(e=>({e})):history?data.equipment.flatMap(e=>e.controls.filter(isInspection).map(c=>({e,c}))):active.filter(e=>kind==='sourceDates'&&e.memoryFlowTracking||kind==='active'||kind==='controlled'&&due(e)&&due(e)>=today()||kind==='missing'&&!latestInspection(e)||kind==='todo'&&['À faire','En retard'].includes(status(e,today()))||statusKinds[kind]&&status(e,today())===statusKinds[kind]||kind.startsWith('result:')&&latestInspection(e)?.result===kind.slice(7)).map(e=>({e}));$('#kpiListTitle').textContent=titles[kind]||'Dernier résultat : '+kind.slice(7);$('#kpiListContent').innerHTML=`<p>${items.length} ${history?'vérification(s) effectuée(s), archives comprises':kind==='lostArchived'?'introuvable(s) avec suivi suspendu':'équipement(s) actif(s)'}</p><div class="owner-equipment-list">${items.length?`<table><thead><tr><th>Équipement</th><th>${history?'Date du contrôle':'Échéance'}</th><th>${history?'Résultat':'État'}</th><th></th></tr></thead><tbody>${items.map(({e,c})=>`<tr class="${archiveRowClass(e)}"><td>${equipmentLabel(e)}${e.archived?badge(e):''}</td><td>${fmt(history?c.date:due(e))}</td><td>${history?esc(c.result):badge(e)}</td><td><button class="secondary" data-kpi-open-equipment="${e.id}">Ouvrir la fiche</button></td></tr>`).join('')}</tbody></table>`:'<p class="empty">Aucun élément dans cette liste.</p>'}</div>`;$('#kpiListContent').querySelectorAll('[data-kpi-open-equipment]').forEach(button=>button.onclick=()=>{$('#kpiListDialog').close();showDetail(button.dataset.kpiOpenEquipment)});$('#kpiListDialog').showModal()}
let monthlyYear=Number(today().slice(0,4));
function renderMonthlyKpi(){const report=monthlyProgress(data.equipment,monthlyYear,today()),names=['Jan','Fév','Mar','Avr','Mai','Juin','Juil','Août','Sep','Oct','Nov','Déc'];$('#monthlyYear').value=monthlyYear;const points=report.months.map((m,i)=>m.completionPercent===null?null:{x:55+i*65,y:220-m.completionPercent*1.8,m}).filter(Boolean);const segments=[];let current=[];report.months.forEach((m,i)=>{if(m.completionPercent===null){if(current.length)segments.push(current);current=[]}else current.push(`${55+i*65},${220-m.completionPercent*1.8}`)});if(current.length)segments.push(current);
$('#monthlyChart').innerHTML=`<svg viewBox="0 0 810 265" role="img" aria-label="Pourcentage des contrôles réalisés par mois, année ${monthlyYear}">${[0,25,50,75,100].map(n=>`<line x1="45" x2="790" y1="${220-n*1.8}" y2="${220-n*1.8}" stroke="#dce5ef"/><text x="3" y="${225-n*1.8}" fill="#60748e" font-size="11">${n}%</text>`).join('')}${segments.map(points=>`<polyline fill="none" stroke="#0057a8" stroke-width="3" points="${points.join(' ')}"/>`).join('')}${points.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="5" fill="#0057a8"/><text x="${p.x}" y="${p.y-12}" text-anchor="middle" font-size="12" fill="#193f69">${p.m.completionPercent}%</text>`).join('')}${names.map((name,i)=>`<text x="${55+i*65}" y="250" text-anchor="middle" font-size="12" fill="#60748e">${name}</text>`).join('')}</svg>`;
$('#monthlyCards').innerHTML=report.months.map((m,i)=>`<article class="month-card"><h3>${names[i]}</h3><strong>${m.completionPercent===null?'Non applicable':m.completionPercent+' %'}</strong><p>${m.done} / ${m.total} fait(s)</p><p>${m.total-m.done} non fait(s) · ${m.excluded} exclusion(s)</p><button class="secondary" data-month-open="${m.month}" ${!m.total?'disabled':''}>Voir les échéances</button><small>Objectif : 100 % réalisés</small></article>`).join('');$('#monthlyHistoryNote').textContent=report.unknownHistory?`${report.unknownHistory} contrôle(s) historique(s) sans date prévue connue : exclus de ce calcul, car leur ancien planning ne peut pas être reconstitué.`:'Les échéances des contrôles réalisés sont conservées pour suivre les mois passés.';$('#monthlyCards').querySelectorAll('[data-month-open]').forEach(button=>button.onclick=()=>openMonthlyRemaining(Number(button.dataset.monthOpen)))}
function openMonthlyRemaining(month){const m=monthlyProgress(data.equipment,monthlyYear,today()).months[month-1],name=new Date(Date.UTC(monthlyYear,month-1,1)).toLocaleDateString('fr-FR',{month:'long',year:'numeric',timeZone:'UTC'});$('#monthlyRemainingTitle').textContent=`Échéances et réalisations — ${name}`;$('#monthlyRemainingList').innerHTML=`<p>${m.done} fait(s) · ${m.total-m.done} non fait(s) · ${m.excluded} hors suivi. Total prévu : ${m.total}.</p><p class="monthly-status-legend"><span class="badge monthly-done">Fait</span><span class="badge monthly-pending">Non fait</span><span class="badge monthly-excluded">Non fait — hors suivi</span></p><div class="owner-equipment-list"><table><thead><tr><th>Équipement</th><th>Date prévue</th><th>État</th><th></th></tr></thead><tbody>${m.entries.map(e=>`<tr class="monthly-${e.done?'done':e.currentExcluded?'excluded':'pending'}-row"><td><b>${esc(e.identifier)}</b><small>${esc(e.name)}</small></td><td>${fmt(e.date)}</td><td>${e.done?'<span class="badge monthly-done">Fait</span>':e.currentExcluded?'<span class="badge monthly-excluded">Non fait — hors suivi</span>':'<span class="badge monthly-pending">Non fait</span>'}${e.controlDate?'<small>Réalisation : '+fmt(e.controlDate)+'</small>':''}</td><td><button class="secondary" data-month-equipment="${e.equipmentId}">Ouvrir la fiche</button></td></tr>`).join('')}</tbody></table></div>`;$('#monthlyRemainingList').querySelectorAll('[data-month-equipment]').forEach(button=>button.onclick=()=>{$('#monthlyRemainingDialog').close();showDetail(button.dataset.monthEquipment)});$('#monthlyRemainingDialog').showModal()}
$('#monthlyYear').onchange=ev=>{const year=Number(ev.target.value);if(!Number.isInteger(year)||year<1900||year>9999){ev.target.value=monthlyYear;return}monthlyYear=year;renderMonthlyKpi()};
function openOwner(owner){selectedOwner=owner;renderOwners();$('#ownerProfileName').focus()}
function renderOwners(){const owners=[...new Map([...data.owners,...data.equipment.flatMap(equipmentOwners)].map(o=>[normalize(o),o])).values()].sort((a,b)=>a.localeCompare(b,'fr'));let cards=owners.map(owner=>({owner,items:data.equipment.filter(e=>equipmentHasOwner(e,owner))}));const unassigned=data.equipment.filter(e=>!equipmentOwners(e).length);if(unassigned.length)cards.push({owner:'',items:unassigned});$('#ownerPicker').innerHTML='<option value="">Choisir un propriétaire</option>'+owners.map(o=>`<option value="${esc(o)}">${esc(o)}</option>`).join('');const query=searchKey($('#ownerSearch').value);cards=cards.filter(c=>searchKey(c.owner+' '+Object.values(data.ownerContacts.find(x=>normalize(x.owner)===normalize(c.owner))||{}).join(' ')+(c.owner?'':' Sans propriétaire')).includes(query));const order=$('#ownerSort').value;cards.sort((a,b)=>order==='count'?b.items.filter(e=>!materialArchived(e)).length-a.items.filter(e=>!materialArchived(e)).length||a.owner.localeCompare(b.owner,'fr'):(order==='za'?-1:1)*a.owner.localeCompare(b.owner,'fr'));$('#ownerTools').hidden=selectedOwner!==null;$('#ownersList').hidden=selectedOwner!==null;$('#ownerProfile').hidden=selectedOwner===null;$('#createOwner').hidden=selectedOwner!==null;if(selectedOwner===null)$('#ownerProfile').innerHTML='';
$('#ownersList').innerHTML=cards.length?cards.map(({owner,items},index)=>`<article class="owner-card" data-owner-card="${index}"><h2>${esc(owner)||'Sans propriétaire'}</h2><p><strong>${items.filter(e=>!materialArchived(e)).length}</strong> équipement(s) en suivi<br>${items.filter(lossArchived).length} introuvable(s) · ${items.filter(materialArchived).length} mis au rebut</p><button class="secondary" data-owner-index="${index}">${owner?'Ouvrir la fiche':'Voir le matériel'}<span class="sr-only"> de ${esc(owner)||'Sans propriétaire'}</span></button></article>`).join(''):'<div class="panel empty">Aucun propriétaire enregistré. Ajoutez un propriétaire puis associez-le à un équipement depuis sa fiche.</div>';$('#ownersList').querySelectorAll('[data-owner-index]').forEach(button=>button.onclick=()=>{const owner=cards[Number(button.dataset.ownerIndex)].owner;if(owner)openOwner(owner);else setView('material','')});
$('#ownersList').querySelectorAll('[data-owner-card]').forEach(card=>card.onclick=ev=>{if(ev.target.closest('button'))return;const owner=cards[Number(card.dataset.ownerCard)].owner;if(owner)openOwner(owner);else setView('material','')});
if(selectedOwner!==null){const items=data.equipment.filter(e=>equipmentHasOwner(e,selectedOwner));$('#ownerProfile').innerHTML=`<section class="panel"><div class="toolbar"><div><p class="eyebrow">VGP · FICHE EMPLOYÉ / PROPRIÉTAIRE</p><h2 id="ownerProfileName" tabindex="-1">${esc(selectedOwner)}</h2></div><button class="secondary" id="backToOwners">Retour aux propriétaires</button><button id="associateEquipment">+ Associer un équipement existant</button>${selectedOwner?'<button type="button" id="deleteOwner" class="danger">Supprimer la fiche</button>':''}</div><p>${items.filter(e=>!materialArchived(e)).length} équipement(s) en suivi · ${items.filter(lossArchived).length} introuvable(s) · ${items.filter(materialArchived).length} mis au rebut</p>${ownerContactHtml(selectedOwner)}<div class="owner-equipment-list">${items.length?`<table><thead><tr><th>Matériel</th><th>Secteur / zone</th><th>Équipe</th><th>Échéance</th><th></th></tr></thead><tbody>${items.map(e=>`<tr class="${archiveRowClass(e)}"><td>${equipmentLabel(e)}</td><td>${esc(e.sector)||'—'}<small>${esc(e.zone)}</small></td><td>${esc(e.team)||'—'}</td><td>${badge(e)}<small>${e.archived?'Suivi suspendu':fmt(due(e))}</small></td><td><button class="secondary" data-open="${e.id}">Ouvrir</button></td></tr>`).join('')}</tbody></table>`:'<p class="empty">Aucun équipement associé à cette personne.</p>'}</div>${ownerReminderHtml(items)}</section>`;$('#ownerContactForm').onsubmit=saveOwnerContact;if($('#deleteOwner'))$('#deleteOwner').onclick=deleteOwnerProfile;$('#ownerContactForm').elements.sector.onchange=updateOwnerZones;$('#ownerContactForm').elements.zone.disabled=$('#ownerContactForm').elements.sector.value!=='B2';$('#ownerProfile').querySelectorAll('[data-reminder-equipment]').forEach(button=>button.onclick=()=>previewReminder(button.dataset.reminderEquipment,button.dataset.reminderKind));$('#backToOwners').onclick=()=>{selectedOwner=null;renderOwners();$('#ownersTitle').focus()};$('#associateEquipment').onclick=()=>{$('#associationSearch').value='';$('#associationError').textContent='';$('#associateOwner').textContent=`Associer du matériel à ${selectedOwner}`;renderAssociationList();$('#associateDialog').showModal()}}}
function validEmail(email){return email.length<=254&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)}
function ownerProfileSelect(field,label,choices,value=''){return `<label>${label}<select name="${field}"><option value="">Non renseigné</option>${choices.map(v=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;}
function ownerContactHtml(owner){const c=data.ownerContacts.find(c=>normalize(c.owner)===normalize(owner))||{};return `<form id="ownerContactForm" class="owner-contact owner-profile-form"><h3>Informations du propriétaire</h3><div class="fields"><label class="wide">Nom du propriétaire *<input name="ownerName" required maxlength="160" value="${esc(owner)}" autocomplete="name"></label><label class="wide">Adresse e-mail<input name="email" type="email" maxlength="254" value="${esc(c.email||'')}" autocomplete="email" placeholder="prenom.nom@entreprise.fr"></label>${ownerProfileSelect('team','Équipe',['A','B','C','D','E','Jour'],c.team)}${ownerProfileSelect('service','Service',['IT','HSE','Métrologie','RH'],c.service)}${ownerProfileSelect('sector','Secteur',['A1','A2','B1','B2','B3'],c.sector)}${ownerProfileSelect('zone','Sous-secteur / zone',c.sector==='B2'?['DMCR','Yuzer']:[],c.zone)}</div><p class="foot" id="ownerZoneHelp">${c.sector==='B2'?'Sous-secteurs disponibles : DMCR et Yuzer.':'Sélectionnez B2 pour choisir DMCR ou Yuzer. Les autres sous-secteurs seront ajoutés ensuite.'}</p><button class="secondary">Enregistrer la fiche propriétaire</button><p id="ownerContactSaved" role="status"></p><p id="ownerContactError" class="error" role="alert"></p></form>`;}
async function deleteOwnerProfile(){
 const owner=selectedOwner,button=$('#deleteOwner');if(!owner||button.disabled)return;
 const count=data.equipment.filter(e=>equipmentHasOwner(e,owner)).length;
 if(!confirm(`Supprimer la fiche de « ${owner} » ?\n\nSes coordonnées seront supprimées et ses associations à ${count} équipement(s) seront retirées. Les équipements, leurs contrôles et leurs rapports seront conservés. Les autres propriétaires resteront associés.\n\nConfirmer la suppression ?`))return;
 button.disabled=true;
 try{const next=copyData(data);next.owners=next.owners.filter(o=>normalize(o)!==normalize(owner));next.ownerContacts=next.ownerContacts.filter(c=>normalize(c.owner)!==normalize(owner));for(const e of next.equipment)if(equipmentHasOwner(e,owner))removeEquipmentOwner(e,owner);
 if(await save(next)){selectedOwner=null;dirtyForms.delete($('#ownerContactForm'));$('#ownerSearch').value='';renderOwners();$('#ownersTitle').focus();$('#message').textContent=`Fiche propriétaire supprimée${memoryOnly?' pour cette session uniquement':''}. Les équipements et leurs historiques sont conservés.`;}else $('#ownerContactError').textContent=$('#message').textContent;
 }finally{button.disabled=false;}
}
function updateOwnerZones(){const f=$('#ownerContactForm'),sector=f.elements.sector.value,zone=f.elements.zone,current=zone.value;zone.innerHTML='<option value="">Non renseigné</option>'+(sector==='B2'?['DMCR','Yuzer'].map(v=>`<option>${v}</option>`).join(''):'');zone.value=sector==='B2'?current:'';zone.disabled=sector!=='B2';$('#ownerZoneHelp').textContent=sector==='B2'?'Sous-secteurs disponibles : DMCR et Yuzer.':'Sélectionnez B2 pour choisir DMCR ou Yuzer. Les autres sous-secteurs seront ajoutés ensuite.';}
async function saveOwnerContact(ev){ev.preventDefault();const f=new FormData(ev.target),owner=selectedOwner,button=ev.target.querySelector('button[type=submit],button:not([type])');if(button.disabled||owner===null)return;const ownerName=f.get('ownerName').trim();if(!ownerName||ownerName.length>160){$('#ownerContactError').textContent='Renseignez un nom de 1 à 160 caractères.';return;}if(normalize(ownerName)!==normalize(owner)&&[...data.owners,...data.equipment.flatMap(equipmentOwners),...data.ownerContacts.map(c=>c.owner)].some(o=>normalize(o)===normalize(ownerName))){$('#ownerContactError').textContent='Ce propriétaire existe déjà. Choisissez un nom distinct pour conserver les deux fiches.';return;}const email=f.get('email').trim();if(email&&!validEmail(email)){$('#ownerContactError').textContent='Renseignez une adresse e-mail valide.';return;}const profile={team:f.get('team')||'',service:f.get('service')||'',sector:f.get('sector')||'',zone:f.get('sector')==='B2'?(f.get('zone')||''):''};if(!ownerProfileFieldsValid(profile)){$('#ownerContactError').textContent='Choisissez les informations dans les listes proposées.';return;}button.disabled=true;try{const next=copyData(data);let contact=next.ownerContacts.find(c=>normalize(c.owner)===normalize(owner));if(!contact){contact={owner,email};next.ownerContacts.push(contact);}contact.email=email;if(ownerName!==owner){next.owners=next.owners.map(o=>normalize(o)===normalize(owner)?ownerName:o);if(!next.owners.some(o=>normalize(o)===normalize(ownerName)))next.owners.push(ownerName);for(const e of next.equipment){if(normalize(e.owner)===normalize(owner))e.owner=ownerName;if(e.additionalOwners)e.additionalOwners=e.additionalOwners.map(o=>normalize(o)===normalize(owner)?ownerName:o);}contact.owner=ownerName;contact.nameHistory=[...(contact.nameHistory||[]),{previousName:owner,name:ownerName,at:new Date().toISOString(),by:accountName()}];}for(const [key,value] of Object.entries(profile))if(value||key in contact)contact[key]=value;if(await save(next)){$('#message').textContent=`Fiche propriétaire enregistrée${memoryOnly?' pour cette session uniquement':''}.`;if(selectedOwner===owner){selectedOwner=ownerName;renderOwners();$('#ownerContactSaved').textContent='Fiche propriétaire enregistrée.';}}else if(selectedOwner===owner)$('#ownerContactError').textContent=$('#message').textContent;}finally{button.disabled=false;}}
function ownerProfileFieldsValid(c){return ['team','service','sector','zone'].every(k=>c[k]===undefined||typeof c[k]==='string')&&(!c.team||['A','B','C','D','E','Jour'].includes(c.team))&&(!c.service||['IT','HSE','Métrologie','RH'].includes(c.service))&&(!c.sector||['A1','A2','B1','B2','B3'].includes(c.sector))&&(!c.zone||c.sector==='B2'&&['DMCR','Yuzer'].includes(c.zone));}

function ownerReminderHtml(items){const rows=items.flatMap(e=>reminders(e).map(r=>({...r,e}))).sort((a,b)=>a.date.localeCompare(b.date)||a.e.identifier.localeCompare(b.e.identifier,'fr'));return `<section class="owner-reminders"><h3>Rappels par e-mail — prévisualisation</h3><aside>Aucun e-mail n’est envoyé actuellement. L’envoi automatique nécessite un serveur et une connexion au service de messagerie. Le message du jour de l’échéance contient une consigne interne de suspension d’usage, à valider avec votre entreprise.</aside><p class="foot">Calendrier recalculé après chaque contrôle ou réaffectation. Les archives sont exclues. « Un mois » signifie un mois calendaire ; les autres délais sont de 14 et 7 jours.</p><div class="owner-equipment-list">${rows.length?`<table><thead><tr><th>Date prévue</th><th>Équipement</th><th>Rappel</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>${fmt(r.date)}<small>${r.date<today()?'Date passée — aucun envoi':r.date===today()?'Prévu aujourd’hui — aucun envoi':'À venir — aucun envoi'}</small></td><td><b>${esc(r.e.identifier)}</b><small>Échéance : ${fmt(r.deadline)}</small></td><td>${r.label}</td><td><button class="secondary" data-reminder-equipment="${r.equipmentId}" data-reminder-kind="${r.kind}">Voir le message</button></td></tr>`).join('')}</tbody></table>`:'<p class="empty">Aucun rappel : aucun équipement actif avec une échéance définie.</p>'}</div></section>`}
function previewReminder(id,kind){const e=data.equipment.find(e=>e.id===id),r=reminders(e).find(r=>r.kind===kind);if(!r)return;const email=equipmentMailRecipients(e,data.ownerContacts).map(r=>r.email||r.owner+' (adresse à renseigner)').join(', '),template=data.mailTemplates.find(t=>t.kind===kind),values=mailValues(e);$('#emailPreviewMeta').textContent=`Date prévue : ${fmt(r.date)} · Destinataire : ${email||'Adresse e-mail à renseigner'}`;$('#emailPreviewSubject').textContent=fillEmailTemplate(template.subject,values);$('#emailPreviewBody').value=fillEmailTemplate(template.body,values)+'\n\nPRÉVISUALISATION DU PROTOTYPE : ce message n’a pas été envoyé.';$('#emailPreview').showModal()}
function defaultMailTemplates(){return ['month','twoWeeks','week','deadline'].map(kind=>({kind,subject:(kind==='deadline'?'Échéance atteinte — suspension d’utilisation':kind==='month'?'Contrôle à prévoir':'Matériel à apporter pour contrôle')+' : {{numero_interne}}',body:'Bonjour {{nom_proprietaire}},\n\nL’équipement {{nom_equipement}} (numéro interne {{numero_interne}}, ID {{id_vgp}}) doit être contrôlé avant le {{date_controle}}.\n\n'+(kind==='deadline'?"Selon la consigne interne proposée, cet équipement ne doit plus être utilisé avant vérification et autorisation selon la procédure de l’entreprise. Cette consigne reste à valider ; elle n’est pas présentée comme une règle réglementaire.":kind==='month'?'Merci de prévoir son contrôle avant cette date.':'Merci d’apporter le matériel pour permettre son contrôle. Le lieu et les modalités seront précisés par l’entreprise.')+'\n\nVérification générale périodique Goodyear Amiens — suivi VGP'}))}
function mailValues(e){return {nom_equipement:equipmentName(e)||'Nom à renseigner',numero_interne:e.identifier||'Numéro à renseigner',id_vgp:e.siteId??'—',nom_proprietaire:equipmentOwners(e).join(', ')||'Propriétaire à renseigner',date_controle:fmt(due(e)),secteur:e.sector||'Non renseigné',zone:e.zone||'Non renseignée'}}
function validTemplates(templates){return Array.isArray(templates)&&templates.length===4&&new Set(templates.map(t=>t?.kind)).size===4&&templates.every(t=>t&&['month','twoWeeks','week','deadline'].includes(t.kind)&&typeof t.subject==='string'&&t.subject.trim()&&t.subject.length<=300&&typeof t.body==='string'&&t.body.trim()&&t.body.length<=10000)}
function renderMailSettings(){renderDigestSettings();$('#mailSampleEquipment').innerHTML=data.equipment.filter(e=>!e.archived).map(e=>`<option value="${e.id}">${esc(e.identifier)} — ${esc(equipmentName(e))}</option>`).join('')||'<option value="">Aucun matériel actif</option>';loadMailTemplate()}
function renderDigestSettings(){const settings=data.digestSettings||{};$('#digestRecipient').value=settings.recipient||'';$('#digestWeek').checked=settings.week!==false;$('#digestMonth').checked=settings.month!==false;renderDigestPreview();}
function renderDigestPreview(){const report=buildDigest(data,$('#digestKind').value,today());$('#digestPreview').textContent=report.subject+'\n\n'+report.text;}
$('#digestKind').onchange=renderDigestPreview;
$('#digestForm').onsubmit=async event=>{event.preventDefault();const recipient=$('#digestRecipient').value.trim();if(!validEmail(recipient))return;const next=copyData(data);next.digestSettings={recipient,week:$('#digestWeek').checked,month:$('#digestMonth').checked,timezone:'Europe/Paris',hour:7};if(await save(next))$('#digestSaved').textContent='Préférences enregistrées. Envoi automatique non activé : configuration serveur nécessaire.';else $('#digestSaved').textContent=$('#message').textContent;};
function loadMailTemplate(){const template=data.mailTemplates.find(t=>t.kind===$('#mailTemplateKind').value);$('#mailSubject').value=template.subject;$('#mailBody').value=template.body;$('#mailTemplateError').textContent='';$('#mailTemplateSaved').textContent='';updateMailPreview()}
function updateMailPreview(){const e=data.equipment.find(e=>e.id===$('#mailSampleEquipment').value);if(!e){$('#mailSettingsPreview').textContent='Ajoutez un équipement actif pour prévisualiser les remplacements.';return}const values=mailValues(e),email=equipmentMailRecipients(e,data.ownerContacts).map(r=>r.email||r.owner+' (adresse à renseigner)').join(', ')||'Adresse à renseigner';$('#mailSettingsPreview').textContent=`Destinataire : ${email}\nObjet : ${fillEmailTemplate($('#mailSubject').value,values)}\n\n${fillEmailTemplate($('#mailBody').value,values)}\n\nSIMULATION : aucun e-mail envoyé.`}
$('#mailTemplateKind').onchange=loadMailTemplate;$('#mailSampleEquipment').onchange=updateMailPreview;$('#mailSubject').oninput=$('#mailBody').oninput=()=>{$('#mailTemplateSaved').textContent='Modifications non enregistrées.';updateMailPreview()};
$('#mailTemplateForm').onsubmit=async ev=>{ev.preventDefault();const next=copyData(data),template=next.mailTemplates.find(t=>t.kind===$('#mailTemplateKind').value);const subject=$('#mailSubject').value.trim(),body=$('#mailBody').value.trim();const tokens=[...subject.matchAll(/\{\{([^{}]*)\}\}/g),...body.matchAll(/\{\{([^{}]*)\}\}/g)].map(m=>m[1].trim()),allowed=['nom_equipement','numero_interne','id_vgp','nom_proprietaire','date_controle','secteur','zone'];const unknown=tokens.filter(t=>!allowed.includes(t));if(unknown.length){$('#mailTemplateError').textContent='Champs inconnus : '+unknown.join(', ');return}template.subject=subject;template.body=body;if(!validTemplates(next.mailTemplates)){$('#mailTemplateError').textContent='Renseignez un objet et un message valides.';return}if(await save(next)){$('#mailTemplateError').textContent='';$('#mailTemplateSaved').textContent=`Modèle enregistré${memoryOnly?' pour cette session uniquement':''}.`;updateMailPreview()}else $('#mailTemplateError').textContent=$('#message').textContent};
$('#settingsToggle').onclick=()=>{$('#settingsToggle').setAttribute('aria-expanded','true');$('#settingsMenu').showModal()};$('#settingsMenu').addEventListener('close',()=>$('#settingsToggle').setAttribute('aria-expanded','false'));$('#settingsMenu').addEventListener('click',ev=>{if(ev.target===$('#settingsMenu')){const r=ev.target.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)ev.target.close()}});

function renderAssociationList(){const q=normalize($('#associationSearch').value);const items=data.equipment.filter(e=>!materialArchived(e)&&normalize([e.identifier,e.designation,e.standardName,e.serialNumber,e.siteId,e.sector,e.zone].join(' ')).includes(q));$('#associationList').innerHTML=items.length?`<table><thead><tr><th>Équipement</th><th>Propriétaire(s) actuel(s)</th><th></th></tr></thead><tbody>${items.map(e=>`<tr><td>${equipmentLabel(e)}</td><td>${esc(equipmentOwners(e).join(', '))||'Non renseigné'}</td><td><button class="secondary" data-associate="${e.id}" ${equipmentHasOwner(e,selectedOwner)?'disabled':''}>${equipmentHasOwner(e,selectedOwner)?'Déjà associé':'Associer'}</button></td></tr>`).join('')}</tbody></table>`:'<p class="empty">Aucun équipement actif correspondant.</p>';$('#associationList').querySelectorAll('[data-associate]').forEach(button=>button.onclick=async()=>{const e=data.equipment.find(e=>e.id===button.dataset.associate),owner=selectedOwner;if(!e||materialArchived(e)||owner===null||button.disabled)return;if(equipmentOwners(e).length&&!confirm(`Associer également l’équipement ${e.identifier} à ${owner} ? Les propriétaires déjà associés seront conservés.`))return;button.disabled=true;try{const next=copyData(data);addEquipmentOwner(next.equipment.find(item=>item.id===e.id),owner);if(await save(next)){$('#associateDialog').close();$('#message').textContent=`Équipement ${e.identifier} associé à ${owner}${memoryOnly?' pour cette session uniquement':''}.`;$('#ownerProfileName').focus();}else $('#associationError').textContent=$('#message').textContent;}catch(error){$('#associationError').textContent=error.message;}finally{button.disabled=false;}});}

$('#associationSearch').oninput=renderAssociationList;
$('#menuToggle').onclick=()=>{$('#menuToggle').setAttribute('aria-expanded','true');$('#navigation').showModal()};
$('#navigation').addEventListener('close',()=>$('#menuToggle').setAttribute('aria-expanded','false'));
