function controllerOptions(current=''){return '<option value="">Choisir un contrôleur</option>'+[...data.controllerProfiles].sort((a,b)=>a.name.localeCompare(b.name,'fr')).map(p=>`<option value="${esc(p.name)}" ${p.name===current?'selected':''}>${esc(p.name)}</option>`).join('');}
function renderVerifierLists(){document.querySelectorAll('[data-controller-list]').forEach(select=>{const current=select.value;select.innerHTML=controllerOptions(current);});}
function verifierInput(required){return `<label>Contrôleur ${required?'*':''}<select name="intervenant" data-controller-list ${required?'required':''}>${controllerOptions()}</select><button type="button" class="secondary" data-add-verifier>+ Ajouter un contrôleur</button><small>La liste provient des fiches de l’onglet Contrôleurs.</small></label>`;}

function equipmentSnapshot(e){const snapshot=Object.fromEntries(['siteId','identifier','serialNumber','designation','location','sector','zone','team','owner','months','comments'].map(key=>[key,e[key]??'']));snapshot.owner=equipmentOwners(e).join(', ');snapshot.additionalOwners=[...(e.additionalOwners||[])];snapshot.originalDesignation=e.originalDesignation||e.designation;snapshot.designation=equipmentName(e);return snapshot}
function fields(required){return `<div class="fields"><label>Date du contrôle ${required?'*':''}<input type="date" name="date" max="${today()}" ${required?'required':''}></label>${verifierInput(required)}<label>Résultat<select name="result"><option value="">Choisir un résultat</option>${results.map(r=>`<option>${r}</option>`).join('')}</select></label><label>Justificatif (PDF ou image, 1 Mo maximum)<input type="file" name="attachment" accept="application/pdf,image/png,image/jpeg,image/webp"></label><label class="wide">Observations<textarea name="observations" maxlength="5000"></textarea></label></div>`}
$('#initialFields').innerHTML=fields(false);$('#controlFields').innerHTML=fields(true);$('#controlForm').elements.result.onchange=updateLossFields;
$('#initial').addEventListener('invalid',()=>{$('#initial').open=true},true);
async function readControl(form,required){const f=new FormData(form),date=f.get('date'),file=f.get('attachment');if(!date){if(required||f.get('intervenant')||f.get('result')||f.get('observations')||file?.size)throw Error('Renseignez la date du contrôle ou laissez tous ses champs vides.');return null}if(f.get('result')==='Introuvable'&&!f.get('observations').trim())throw Error('Décrivez les recherches effectuées pour déclarer le matériel introuvable.');if(date>today())throw Error('Un contrôle réalisé ne peut pas être daté dans le futur.');if(f.get('intervenant').trim().length>160)throw Error('Le nom du vérificateur est limité à 160 caractères.');if(!f.get('result')||!f.get('intervenant').trim())throw Error('Renseignez le résultat et le contrôleur.');const verifier=data.controllerProfiles.find(p=>p.name===f.get('intervenant'));if(!verifier)throw Error('Choisissez un contrôleur enregistré dans sa fiche.');let attachment=null;if(file?.size){if(file.size>1024*1024)throw Error('Le justificatif dépasse 1 Mo.');if(!['application/pdf','image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Utilisez un PDF ou une image PNG, JPEG ou WebP.');const url=await new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Lecture du fichier impossible.'));r.readAsDataURL(file)});attachment={name:file.name,type:file.type,url}}const id=uuid();return {id,reportId:nextReportNumber(data),date,verifierId:verifier.id,verifierSnapshot:{id:verifier.id,name:verifier.name,email:verifier.email},intervenant:verifier.name,result:f.get('result'),observations:f.get('observations'),attachment,created:Date.now(),enteredBy:accountName(),enteredById:cloud?.session?.user?.id||null}}
function edit(id=null){editing=id;const e=data.equipment.find(e=>e.id===id);$('#equipmentForm').reset();$('#equipmentError').textContent='';for(const field of ['sector','team']){$('#'+field+'RequiredError').textContent='';$('#equipmentForm').elements[field].setAttribute('aria-invalid','false');}$('#initial').hidden=!!e;$('#initial').open=false;loadDateValidation(e);$('#editorTitle').textContent=e?'Modifier l’équipement':'Ajouter un équipement';ownerOptions(e?.owner);if(e)for(const k of ['identifier','serialNumber','sector','zone','team','designation','location','months'])$('#equipmentForm').elements[k].value=e[k];$('#equipmentForm').elements.manualNextControlDate.value=e?.manualNextControlDate&&(e.manualControlId??null)===(latest(e)?.id??null)?e.manualNextControlDate:'';$('#manualDateFields').hidden=!$('#equipmentForm').elements.manualNextControlDate.value;loadNamingFields(e?(e.typeId||'__free__'):'',e?.variantId||'');updateEquipmentZones();checkDuplicates();$('#editor').showModal()}
$('#add').onclick=()=>edit();$('#toggleManualDate').onclick=()=>{const fields=$('#manualDateFields');fields.hidden=!fields.hidden;if(fields.hidden)$('#equipmentForm').elements.manualNextControlDate.value='';else $('#equipmentForm').elements.manualNextControlDate.focus()};
