$('#controlForm').onsubmit=async ev=>{ev.preventDefault();try{const c=await readControl(ev.target,true),next=copyData(data);c.enteredBy=accountName();c.enteredById=cloud?.session?.user?.id||null;const equipment=next.equipment.find(e=>e.id===selected);if(equipment.archived&&!(controlContext==='scrapCompletion'&&needsScrapControl(equipment)))throw Error('Désarchivez cet équipement avant d’enregistrer un contrôle.');if(controlContext==='scrapCompletion'&&c.result!=='Mauvais état — à jeter')throw Error('Le résultat d’une mise au rebut doit être « Mauvais état — à jeter ».');if(c.result==='Introuvable'){declareLoss(equipment,{id:c.id,date:c.date,author:c.intervenant,comment:c.observations,account:accountName(),attachment:c.attachment,reportId:c.reportId,equipmentSnapshot:equipmentSnapshot(equipment),verifierId:c.verifierId});}else{if(equipment.needsReverification&&c.date<equipment.lastFoundDate)throw Error('Le nouveau contrôle doit être réalisé après la réactivation.');if(!latestInspection(equipment)||c.date>=latestInspection(equipment).date)c.plannedDate=due(equipment);c.equipmentSnapshot=equipmentSnapshot(equipment);equipment.controls.push(c);equipment.needsReverification=false;}if(controlContext==='scrapCompletion')lastArchive(equipment).controlId=c.id;equipment.scheduledControl=null;if(await save(next)){$('#control').close();showDetail(selected);$('#message').textContent=`${c.result==='Introuvable'?'Introuvable — suivi suspendu. Aucun contrôle réalisé ajouté':'Contrôle enregistré'}${memoryOnly?' pour cette session uniquement':''}.`}else{$('#controlError').textContent=$('#message').textContent}}catch(e){$('#controlError').textContent=e.message}};
