$('#reportLogoFile').onchange=async ev=>{try{const file=ev.target.files[0];if(!file)return;if(!['image/png','image/jpeg'].includes(file.type)||file.size>2*1024*1024)throw Error('Utilisez un logo PNG ou JPEG de 2 Mo maximum.');const url=URL.createObjectURL(file),img=new Image();try{await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('Image illisible.'));img.src=url});const scale=Math.min(1,1200/img.width,800/img.height),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);const next=copyData(data);next.reportLogo={width:canvas.width,height:canvas.height,data:canvas.toDataURL('image/jpeg',.94).split(',')[1]};if(next.reportLogo.data.length>2000000)throw Error('Le logo converti est trop volumineux. Utilisez une image plus petite.');if(await save(next)){renderReportSettings();$('#reportLogoError').textContent=''}else $('#reportLogoError').textContent=$('#message').textContent}finally{URL.revokeObjectURL(url)}}catch(error){$('#reportLogoError').textContent=error.message}finally{ev.target.value=''}};
