function renderNamingGroups(){invalidateNamingPreview();const groups=namingGroups(data.equipment,{search:$('#namingSearch').value,includeNamed:$('#includeNamed').checked}),eligible=new Set(namingGroups(data.equipment,{includeNamed:$('#includeNamed').checked}).flatMap(g=>g.equipment.map(e=>e.id)));namingSelection=new Set([...namingSelection].filter(id=>eligible.has(id)));$('#namingCount').textContent=`${groups.length} noms actuels · ${groups.reduce((n,g)=>n+g.equipment.length,0)} équipements, archives comprises · ${namingSelection.size} sélectionnés`;$('#namingGroups').innerHTML=groups.length?groups.map((g,i)=>`<label class="naming-group"><input type="checkbox" data-naming-group="${i}" ${g.equipment.every(e=>namingSelection.has(e.id))?'checked':''}><span>${esc(g.name)}<small>${g.equipment.length} équipement(s) · ${g.equipment.filter(materialArchived).length} mis au rebut · ${g.equipment.filter(lossArchived).length} introuvable(s)</small></span></label>`).join(''):'<p>Aucun nom à standardiser dans cette sélection.</p>';$('#namingGroups').querySelectorAll('[data-naming-group]').forEach(input=>input.onchange=()=>{const g=groups[Number(input.dataset.namingGroup)];for(const e of g.equipment)if(input.checked)namingSelection.add(e.id);else namingSelection.delete(e.id);invalidateNamingPreview();$('#namingCount').textContent=`${groups.length} noms actuels · ${namingSelection.size} équipements sélectionnés, archives comprises`;});}
