$('#previewNaming').onclick=()=>{try{if(!namingSelection.size)throw Error('Sélectionnez au moins un groupe de noms.');const typeId=$('#bulkNamingType').value,variantId=$('#bulkNamingVariant').value;if(!typeId)throw Error('Choisissez le type cible.');const label=standardizedLabel(data.equipmentTypes,typeId,variantId),items=data.equipment.filter(e=>namingSelection.has(e.id));namingPreview={document:canonical(data),ids:items.map(e=>e.id),typeId,variantId,label};$('#namingPreview').innerHTML=`<h3 id="namingPreviewCount">${items.length} fiche(s) → ${esc(label)}</h3><p>Vérifiez chaque ligne avant confirmation. Les noms d’origine, documents, contrôles et échéances sont conservés.</p><div class="naming-preview"><table><thead><tr><th>Inclure</th><th>Numéro interne / ID</th><th>Nom actuel / secteur</th><th>Nom standard proposé</th></tr></thead><tbody>${items.map(e=>`<tr><td><input type="checkbox" data-naming-include="${esc(e.id)}" checked aria-label="Inclure ${esc(e.identifier)}"></td><td>${esc(e.identifier)} · ID ${e.siteId}${e.archived?(lossArchived(e)?' · Introuvable':' · Mis au rebut'):''}</td><td>${esc(e.designation)}<br>${esc(e.sector||'Secteur non renseigné')} ${esc(e.zone||'')}${e.standardName?'<br>Actuellement : '+esc(e.standardName):''}</td><td>${esc(label)}</td></tr>`).join('')}</tbody></table></div>`;$('#namingPreview').querySelectorAll('[data-naming-include]').forEach(input=>input.onchange=()=>{if(input.checked)namingSelection.add(input.dataset.namingInclude);else namingSelection.delete(input.dataset.namingInclude);namingPreview.ids=items.filter(e=>namingSelection.has(e.id)).map(e=>e.id);$('#namingPreviewCount').textContent=namingPreview.ids.length+' fiche(s) → '+label;$('#applyNaming').disabled=namingPreview.ids.length===0;$('#namingCount').textContent=namingPreview.ids.length+' équipement(s) sélectionné(s) après vérification';});$('#namingError').textContent='';$('#applyNaming').disabled=false;}catch(error){$('#namingError').textContent=error.message;}};
